-- =============================================================================
-- 446 — LE CAHIER D'EXERCICES DE TLE (partie 11)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/Tle/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 446 --niveau Tle --matieres maths-complementaires,maths-techno --suffixe 11 > supabase/contenu/446_exercices_tle_11.sql
--
-- 90 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   maths-complementaires.k173  24 exercices · 8 chapitres
--   maths-complementaires.k174  21 exercices · 7 chapitres
--   maths-techno.k176       24 exercices · 8 chapitres
--   maths-techno.k177       21 exercices · 7 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('0df44c0c-64c7-58d6-ac06-86978d6d826b'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le forfait de la salle de sport","competence":"modeliser","situation":"Inès s’inscrit à une salle de sport : 30 € de frais d’inscription, puis 25 € par mois. Le tableau donne la somme totale payée après chaque mois.","documents":[{"id":"forfait","type":"tableau","titre":"Somme totale payée","colonnes":["Mois écoulés","0","1","2","3","4"],"lignes":[["Total payé (€)",30,55,80,105,130]],"enteteLignes":true,"source":"Valeurs imaginées pour l’exercice"}],"questions":[{"enonce":"Touche la somme totale payée après 3 mois.","aide":"Repère la colonne « 3 » puis lis la case de la ligne du total.","type":"zone","document":"forfait","multiple":false},{"enonce":"De combien la somme augmente-t-elle chaque mois ? Donne la raison r de la suite.","aide":"Compare deux colonnes voisines.","type":"nombre","unite":"€"},{"enonce":"Calcule la somme payée après 12 mois avec u(n) = 30 + 25 n.","aide":"Remplace n par 12.","type":"nombre","unite":"€"},{"enonce":"Pourquoi ce forfait est-il modélisé par une suite arithmétique et non géométrique ?","aide":"Regarde ce qui est constant : les différences ou les quotients ?","type":"choix","options":[{"id":"a","texte":"Parce que la somme payée double régulièrement tous les mois"},{"id":"b","texte":"Parce qu’on multiplie la somme payée par 25 chaque mois"},{"id":"c","texte":"Parce que le pourcentage appliqué reste le même chaque mois"},{"id":"d","texte":"Parce qu’on ajoute la même somme à chaque mois qui passe"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c4"]},"explication":"Après 3 mois, Inès a payé **105 €** : 30 + 3 × 25."},{"cle":{"type":"nombre","valeur":25,"tolerance":0},"affichage":"25 €","explication":"Chaque mois on **ajoute** 25 € : la suite est arithmétique de raison **25**."},{"cle":{"type":"nombre","valeur":330,"tolerance":0},"affichage":"330 €","explication":"u(12) = 30 + 25 × 12 = 30 + 300 = **330 €**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Les différences sont constantes (+25), pas les quotients : c’est une suite **arithmétique**."}]$ex$::jsonb),
  ('0df44c0c-64c7-58d6-ac06-86978d6d826b'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le capital de Nadia","competence":"modeliser","situation":"Nadia place 2 500 € à intérêts composés au taux de 3 % par an. Le graphique montre son capital u(n) au bout de n années, arrondi à l’euro près.","documents":[{"id":"cap","type":"graphique","forme":"courbe","titre":"Capital en fonction du temps","categories":["0","1","2","3","4","5"],"series":[{"nom":"Capital","valeurs":[2500,2575,2652,2732,2814,2898]}],"axeY":{"titre":"Capital","unite":"€","min":2400,"max":3000,"pas":100},"axeX":{"titre":"Années écoulées"},"valeurs":false,"source":"Valeurs imaginées pour l’exercice"}],"questions":[{"enonce":"Par quel coefficient multiplicateur le capital est-il multiplié chaque année ?","aide":"Une hausse de 3 % se traduit par 1 + 3/100.","type":"nombre"},{"enonce":"Calcule u(2) = 2 500 × 1,03², arrondi au centime.","aide":"1,03² = 1,0609.","type":"nombre","unite":"€"},{"enonce":"Touche la première année où le capital dépasse 2 800 €.","aide":"Cherche le premier point au-dessus de la graduation 2 800.","type":"zone","document":"cap","multiple":false},{"enonce":"Quelle est la hausse globale du capital en 5 ans, en pourcentage, arrondie au dixième ?","aide":"Calcule 1,03⁵ puis retire 1.","type":"nombre","unite":"%"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":1.03,"tolerance":0},"affichage":"1,03","explication":"Hausse de 3 % : coefficient **1,03**, donc u(n+1) = 1,03 × u(n)."},{"cle":{"type":"nombre","valeur":2652.25,"tolerance":0.01},"affichage":"2652,25 €","explication":"u(2) = 2 500 × 1,0609 = **2 652,25 €**."},{"cle":{"type":"zone","ids":["k4"]},"explication":"Le capital est de 2 732 € après 3 ans et de **2 814 €** après 4 ans : c’est la 4e année."},{"cle":{"type":"nombre","valeur":15.9,"tolerance":0.05},"affichage":"15,9 %","explication":"1,03⁵ ≈ 1,1593 : la hausse globale est d’environ **15,9 %**, et non 5 × 3 = 15 %."}]$ex$::jsonb),
  ('0df44c0c-64c7-58d6-ac06-86978d6d826b'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le lac et ses truites","competence":"modeliser","situation":"Dans un lac, 20 % des truites disparaissent chaque année et une association en réintroduit 60. On note u(n) le nombre de truites après n années, avec u(0) = 100 : u(n+1) = 0,8 u(n) + 60.","documents":[{"id":"truites","type":"tableau","titre":"Effectif des truites","colonnes":["Année n","0","1","2","3","4"],"lignes":[["u(n)",100,140,172,197.6,218.08]],"enteteLignes":true,"source":"Valeurs imaginées pour l’exercice"},{"id":"meth","type":"texte","genre":"consigne","titre":"La méthode","blocs":["1. On cherche le point fixe L tel que L = 0,8 L + 60.","2. On pose v(n) = u(n) − L : c’est une suite géométrique de raison 0,8.","3. On en déduit v(n) puis u(n) = v(n) + L."]}],"questions":[{"enonce":"Calcule u(5) à partir de u(4), arrondi au centième.","aide":"u(5) = 0,8 × u(4) + 60, avec u(4) lu dans le tableau.","type":"nombre"},{"enonce":"Résous L = 0,8 L + 60 pour trouver le point fixe L.","aide":"Regroupe : 0,2 L = 60.","type":"nombre"},{"enonce":"Calcule v(0) = u(0) − L.","aide":"Utilise u(0) = 100 et L = 300.","type":"nombre"},{"enonce":"Calcule v(3) = v(0) × 0,8³, puis compare avec u(3) − 300 lu dans le tableau.","aide":"0,8³ = 0,512.","type":"nombre"},{"enonce":"Vers quelle valeur le nombre de truites se stabilise-t-il à long terme ?","aide":"La raison 0,8 est comprise entre −1 et 1 : v(n) tend vers 0.","type":"choix","options":[{"id":"a","texte":"Vers 100 truites, le nombre présent dans le lac au départ"},{"id":"b","texte":"Vers 60 truites, le nombre réintroduit chaque année"},{"id":"c","texte":"Vers 300 truites, le point fixe trouvé par la méthode"},{"id":"d","texte":"Il augmente sans limite, sans jamais se stabiliser nulle part"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":234.46,"tolerance":0.01},"affichage":"234,46","explication":"u(5) = 0,8 × 218,08 + 60 = **234,46**."},{"cle":{"type":"nombre","valeur":300,"tolerance":0},"affichage":"300","explication":"0,2 L = 60 donc **L = 300**."},{"cle":{"type":"nombre","valeur":-200,"tolerance":0},"affichage":"−200","explication":"v(0) = 100 − 300 = **−200**."},{"cle":{"type":"nombre","valeur":-102.4,"tolerance":0.01},"affichage":"−102,4","explication":"v(3) = −200 × 0,512 = **−102,4**, et 197,6 − 300 = −102,4 : les deux méthodes concordent."},{"cle":{"type":"choix","ids":["c"]},"explication":"v(n) tend vers 0, donc u(n) tend vers **300** : l’effectif se stabilise quelle que soit sa valeur de départ."}]$ex$::jsonb),
  ('aa61edbc-930d-5e21-891b-26764311c4fd'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Une ville qui grandit","competence":"modeliser","situation":"La ville de Marenne compte 12 000 habitants. Sa population augmente de 2 % par an. Le tableau donne les premiers termes de la suite u(n) (arrondis à l’unité).","documents":[{"id":"pop","type":"tableau","titre":"Population de Marenne","colonnes":["Année n","0","1","2"],"lignes":[["u(n)",12000,12240,12485]],"enteteLignes":true,"source":"Valeurs imaginées pour l’exercice"}],"questions":[{"enonce":"Quelle est la raison q de la suite géométrique u ?","aide":"Une hausse de 2 % correspond à 1 + 2/100.","type":"nombre"},{"enonce":"Touche la population de la 2e année.","aide":"La ligne u(n), colonne « 2 ».","type":"zone","document":"pop","multiple":false},{"enonce":"Calcule u(3) = 12 000 × 1,02³, arrondi à l’unité.","aide":"1,02³ ≈ 1,0612.","type":"nombre"},{"enonce":"Comment calculer u(40) sans calculer les 39 termes précédents ?","aide":"Quel mode de définition donne n’importe quel terme directement ?","type":"choix","options":[{"id":"a","texte":"En multipliant 12 000 par 1,02 puis par 40 seulement"},{"id":"b","texte":"En ajoutant 40 fois 0,02 à la population de départ"},{"id":"c","texte":"En utilisant la forme explicite u(n) = 12 000 × 1,02^n"},{"id":"d","texte":"En utilisant la forme u(n) = 12 000 × 0,02^n"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":1.02,"tolerance":0},"affichage":"1,02","explication":"Hausse de 2 % : **q = 1,02**."},{"cle":{"type":"zone","ids":["r0c3"]},"explication":"Après 2 ans : **12 485 habitants** (valeur arrondie)."},{"cle":{"type":"nombre","valeur":12734,"tolerance":1},"affichage":"12 734","explication":"u(3) = 12 000 × 1,061208 ≈ **12 734 habitants**."},{"cle":{"type":"choix","ids":["c"]},"explication":"La forme **explicite** donne u(40) d’un seul calcul : 12 000 × 1,02⁴⁰."}]$ex$::jsonb),
  ('aa61edbc-930d-5e21-891b-26764311c4fd'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Combien d’années pour doubler ?","competence":"programmer","situation":"Un capital de 500 € est placé à 6 % par an. Un algorithme cherche le nombre d’années après lequel le capital dépasse 1 000 €. Le graphique montre le capital, arrondi à l’euro.","documents":[{"id":"algo","type":"texte","genre":"consigne","titre":"L’algorithme","blocs":["n ← 0","u ← 500","Tant que u < 1000 :","    u ← u × 1,06","    n ← n + 1"]},{"id":"capital","type":"graphique","forme":"courbe","titre":"Capital en fonction des années","categories":["0","2","4","6","8","10","12","14"],"series":[{"nom":"Capital","valeurs":[500,562,631,709,797,895,1006,1130]}],"axeY":{"titre":"Capital","unite":"€","min":400,"max":1200,"pas":200},"axeX":{"titre":"Années écoulées"},"valeurs":false,"source":"Valeurs imaginées pour l’exercice"}],"questions":[{"enonce":"Que vaut u après le premier passage dans la boucle ?","aide":"u devient 500 × 1,06.","type":"nombre","unite":"€"},{"enonce":"Touche la première date du graphique où le capital dépasse 1 000 €.","aide":"Cherche le premier point qui passe au-dessus de la graduation 1 000.","type":"zone","document":"capital","multiple":false},{"enonce":"Calcule u(11) = 500 × 1,06¹¹, arrondi au centime.","aide":"1,06¹¹ ≈ 1,8983.","type":"nombre","unite":"€"},{"enonce":"Quelle valeur de n l’algorithme affiche-t-il à la fin ?","aide":"Compare u(11) et u(12) à 1 000.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":530,"tolerance":0},"affichage":"530 €","explication":"u = 500 × 1,06 = **530**, et n vaut 1."},{"cle":{"type":"zone","ids":["k6"]},"explication":"Après 10 ans le capital est de 895 € ; après **12 ans** il est de 1 006 €."},{"cle":{"type":"nombre","valeur":949.15,"tolerance":0.01},"affichage":"949,15 €","explication":"u(11) = 500 × 1,898299 ≈ **949,15 €** : pas encore 1 000 €."},{"cle":{"type":"nombre","valeur":12,"tolerance":0},"affichage":"12","explication":"u(11) = 949,15 est inférieur à 1 000 et u(12) ≈ 1 006,10 le dépasse : l’algorithme affiche **n = 12**."}]$ex$::jsonb),
  ('aa61edbc-930d-5e21-891b-26764311c4fd'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une nappe qui se purifie","competence":"modeliser","situation":"Une nappe phréatique contient 50 mg de polluant par litre. Chaque année, 10 % du polluant est éliminé et une usine en rejette 2 mg/L : c(n+1) = 0,9 c(n) + 2. On admet que c(n) = 30 × 0,9^n + 20.","documents":[{"id":"nappe","type":"graphique","forme":"courbe","titre":"Concentration en polluant","categories":["0","5","10","15","20","25","30"],"series":[{"nom":"Concentration","valeurs":[50,37.7,30.5,26.2,23.6,22.2,21.3]}],"axeY":{"titre":"Concentration","unite":"mg/L","min":0,"max":60,"pas":10},"axeX":{"titre":"Années écoulées"},"valeurs":false,"source":"Valeurs imaginées pour l’exercice"},{"id":"modele","type":"texte","genre":"consigne","titre":"Le modèle","blocs":["Point fixe L : L = 0,9 L + 2.","v(n) = c(n) − L est géométrique de raison 0,9."]}],"questions":[{"enonce":"Résous L = 0,9 L + 2 pour trouver le point fixe L.","aide":"0,1 L = 2.","type":"nombre","unite":"mg/L"},{"enonce":"Touche la première date où la concentration passe sous 30 mg/L.","aide":"Lis la hauteur de chaque point et cherche le premier sous la graduation 30.","type":"zone","document":"nappe","multiple":false},{"enonce":"Calcule c(10) = 30 × 0,9¹⁰ + 20, arrondi au centième.","aide":"0,9¹⁰ ≈ 0,3487.","type":"nombre","unite":"mg/L"},{"enonce":"Que dit la limite de c(n) sur la qualité de l’eau à très long terme ?","aide":"La limite de 0,9^n est 0.","type":"choix","options":[{"id":"a","texte":"La concentration se stabilise à 20 mg/L, niveau d’équilibre"},{"id":"b","texte":"La concentration revient à sa valeur de départ, 50 mg/L"},{"id":"c","texte":"La concentration augmente sans limite, à cause de l’usine"},{"id":"d","texte":"La concentration finit par disparaître et l’eau devient pure"}],"multiple":false},{"enonce":"Combien d’années faut-il au minimum pour que c(n) soit inférieur à 24 mg/L ? (30 × 0,9^n < 4)","aide":"Utilise ln(4/30) ÷ ln(0,9) et arrondis dans le bon sens.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20 mg/L","explication":"0,1 L = 2 donc **L = 20 mg/L**."},{"cle":{"type":"zone","ids":["k3"]},"explication":"À 10 ans la concentration est de 30,5 mg/L ; à **15 ans** elle est de 26,2 mg/L."},{"cle":{"type":"nombre","valeur":30.46,"tolerance":0.01},"affichage":"30,46 mg/L","explication":"c(10) = 30 × 0,348678 + 20 ≈ **30,46 mg/L**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Comme 0,9^n tend vers 0, c(n) tend vers **20** : l’usine empêche l’eau de devenir pure."},{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20","explication":"n > ln(4/30) ÷ ln(0,9) ≈ 19,12 : le plus petit entier est **n = 20**."}]$ex$::jsonb),
  ('e39de060-0e3b-56ad-b11f-8d067217a649'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le bénéfice de la boulangerie","competence":"lire-graphique","situation":"Une boulangerie vend x centaines de viennoiseries par jour. Son bénéfice, en centaines d’euros, est B(x) = −x² + 8x − 7 pour x entre 1 et 7. Le graphique en donne quelques valeurs.","documents":[{"id":"benef","type":"graphique","forme":"courbe","titre":"Bénéfice selon la quantité","categories":["1","2","3","4","5","6","7"],"series":[{"nom":"B(x)","valeurs":[0,5,8,9,8,5,0]}],"axeY":{"titre":"Bénéfice","unite":"centaines d’euros","min":0,"max":10,"pas":2},"axeX":{"titre":"Quantité vendue (centaines)"},"valeurs":false,"source":"Valeurs imaginées pour l’exercice"}],"questions":[{"enonce":"Touche la quantité qui donne le bénéfice le plus grand.","aide":"Cherche le point le plus haut de la courbe.","type":"zone","document":"benef","multiple":false},{"enonce":"La dérivée est B′(x) = −2x + 8. Calcule B′(1).","aide":"Remplace x par 1.","type":"nombre"},{"enonce":"Pour quelle valeur de x la dérivée B′(x) = −2x + 8 s’annule-t-elle ?","aide":"Résous −2x + 8 = 0.","type":"nombre"},{"enonce":"Que peut-on dire de B après x = 4 ?","aide":"Calcule B′(5).","type":"choix","options":[{"id":"a","texte":"B′ est nulle, donc B reste constante sur [4 ; 7]"},{"id":"b","texte":"B′ est positive, donc B est croissante sur [4 ; 7]"},{"id":"c","texte":"B′ est négative, donc B est décroissante sur [4 ; 7]"},{"id":"d","texte":"B′ change de signe, donc B n’est pas définie sur [4 ; 7]"}],"multiple":false}]}$ex$::jsonb,
