   $ex$[{"cle":{"type":"zone","ids":["r1c4"]},"explication":"Pour n = 3, ln(u(3)) = ln 337,5 ≈ **5,822**."},{"cle":{"type":"nombre","valeur":0.41,"tolerance":0.01},"affichage":"0,41","explication":"5,011 − 4,605 ≈ **0,41**, et c’est aussi ln(1,5) ≈ 0,405."},{"cle":{"type":"choix","ids":["a"]},"explication":"ln(u(n)) est une suite arithmétique : u(n) est **géométrique**, de raison q = e^0,405 = 1,5."},{"cle":{"type":"nombre","valeur":1.5,"tolerance":0},"affichage":"1,5","explication":"150 ÷ 100 = **1,5** : +50 % d’inscrits chaque mois."},{"cle":{"type":"nombre","valeur":1139.06,"tolerance":0.01},"affichage":"1139,06","explication":"u(6) = 100 × 11,390625 = **1 139,06** inscrits."}]$ex$::jsonb),
  ('fc9c9b25-fb32-5b87-a4a2-8efa831020d9'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le médicament qui s’élimine","competence":"resoudre","situation":"Chaque heure, le corps élimine 12 % du médicament restant : la quantité est multipliée par 0,88. Une nouvelle dose n’est possible que lorsqu’il reste moins de 5 % de la quantité initiale. Le tableau donne le pourcentage restant.","documents":[{"id":"reste","type":"tableau","titre":"Pourcentage restant","colonnes":["Heures n","0","10","20","25"],"lignes":[["Reste (%)",100,27.9,7.8,4.1]],"enteteLignes":true,"source":"Valeurs imaginées pour l’exercice"},{"id":"meth","type":"texte","genre":"consigne","titre":"La méthode","blocs":["On résout 0,88^n < 0,05.","On applique ln, croissante : n × ln(0,88) < ln(0,05).","ln(0,88) est négatif."]}],"questions":[{"enonce":"Touche la première colonne où il reste moins de 5 %.","aide":"Cherche la première valeur de la ligne sous 5.","type":"zone","document":"reste","multiple":false},{"enonce":"Que devient le sens de l’inégalité quand on divise par ln(0,88) ?","aide":"Signe de ln(0,88) : 0,88 est inférieur à 1.","type":"choix","options":[{"id":"a","texte":"Il s’inverse, car ln(0,05) est un nombre positif"},{"id":"b","texte":"Il s’inverse, car ln(0,88) est un nombre négatif"},{"id":"c","texte":"Il est conservé, car on divise les deux membres"},{"id":"d","texte":"Il est conservé, car ln(0,88) est un nombre positif"}],"multiple":false},{"enonce":"Calcule ln(0,05) ÷ ln(0,88), arrondi au centième.","aide":"ln 0,05 ≈ −2,9957 et ln 0,88 ≈ −0,1278.","type":"nombre"},{"enonce":"Au bout de combien d’heures entières peut-on donner une nouvelle dose ?","aide":"n doit être strictement plus grand que 23,43.","type":"nombre"},{"enonce":"Quel pourcentage reste-t-il après 24 heures ? Arrondis au centième.","aide":"Calcule 100 × 0,88²⁴.","type":"nombre","unite":"%"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c4"]},"explication":"À 20 heures il reste 7,8 % ; à **25 heures** 4,1 %."},{"cle":{"type":"choix","ids":["b"]},"explication":"ln(0,88) < 0 : diviser par un négatif **inverse** l’inégalité, d’où n > ln(0,05) ÷ ln(0,88)."},{"cle":{"type":"nombre","valeur":23.43,"tolerance":0.01},"affichage":"23,43","explication":"Le quotient vaut environ **23,43**."},{"cle":{"type":"nombre","valeur":24,"tolerance":0},"affichage":"24","explication":"n > 23,43 : le plus petit entier est **24 heures**."},{"cle":{"type":"nombre","valeur":4.66,"tolerance":0.01},"affichage":"4,66 %","explication":"0,88²⁴ ≈ 0,0466 : il reste **4,66 %**, sous la barre des 5 %."}]$ex$::jsonb),
  ('75d21456-1d9c-5eda-8771-6014ede38951'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"La vitesse de disparition","competence":"modeliser","situation":"La concentration d’un produit dans le sang (en mg/L) est c(t) = 12 e^(−0,2 t), avec t en heures. Sa dérivée est c′(t) = −2,4 e^(−0,2 t), car il faut multiplier par la dérivée −0,2 de l’exposant.","documents":[{"id":"conc","type":"graphique","forme":"courbe","titre":"Concentration dans le sang","categories":["0","1","2","3","4","5"],"series":[{"nom":"c(t)","valeurs":[12,9.82,8.04,6.59,5.39,4.41]}],"axeY":{"titre":"Concentration","unite":"mg/L","min":0,"max":14,"pas":2},"axeX":{"titre":"Temps en heures"},"valeurs":false,"source":"Valeurs imaginées pour l’exercice"}],"questions":[{"enonce":"Calcule c′(0) avec c′(t) = −2,4 e^(−0,2 t).","aide":"e⁰ = 1.","type":"nombre","unite":"mg/L par h"},{"enonce":"Touche la première heure où la concentration passe sous 6 mg/L.","aide":"Cherche le premier point sous la graduation 6.","type":"zone","document":"conc","multiple":false},{"enonce":"L’équation de la tangente en 0 est y = c′(0)(t − 0) + c(0). Quelle valeur donne-t-elle pour t = 1 ?","aide":"y = −2,4 t + 12.","type":"nombre"},{"enonce":"Que dit le signe de c′(t) sur le phénomène ?","aide":"e^(−0,2 t) est toujours positif.","type":"choix","options":[{"id":"a","texte":"c′ est positive : la concentration diminue à chaque instant"},{"id":"b","texte":"c′ est négative : la concentration augmente à chaque instant"},{"id":"c","texte":"c′ est nulle : la concentration reste stable à chaque instant"},{"id":"d","texte":"c′ est négative : la concentration diminue à chaque instant"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":-2.4,"tolerance":0},"affichage":"−2,4 mg/L par h","explication":"c′(0) = −2,4 × 1 = **−2,4** mg/L par heure."},{"cle":{"type":"zone","ids":["k4"]},"explication":"À 3 heures c = 6,59 ; à **4 heures** c = 5,39 : c’est sous 6."},{"cle":{"type":"nombre","valeur":9.6,"tolerance":0.01},"affichage":"9,6","explication":"y = −2,4 × 1 + 12 = **9,6**, proche de la vraie valeur c(1) ≈ 9,82."},{"cle":{"type":"choix","ids":["d"]},"explication":"Comme −2,4 e^(−0,2t) < 0, c est **décroissante** : le produit disparaît du sang."}]$ex$::jsonb),
  ('75d21456-1d9c-5eda-8771-6014ede38951'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Le bon nombre de publicités","competence":"modeliser","situation":"Une marque diffuse x centaines de publicités. Son bénéfice, en milliers d’euros, est B(x) = 10 ln(x + 1) − 2x pour x ≥ 0. Pour ln(x + 1), la dérivée est 1/(x + 1) : B′(x) = 10/(x + 1) − 2.","documents":[{"id":"pub","type":"tableau","titre":"Bénéfice selon la diffusion","colonnes":["x (centaines)","0","2","4","6","8"],"lignes":[["B(x)",0,6.986,8.094,7.459,5.972]],"enteteLignes":true,"source":"Valeurs imaginées pour l’exercice"}],"questions":[{"enonce":"Calcule B′(1) = 10/(1 + 1) − 2.","aide":"10 ÷ 2 = 5.","type":"nombre"},{"enonce":"Pour quelle valeur de x a-t-on 10/(x + 1) = 2 ?","aide":"Résous x + 1 = 5.","type":"nombre"},{"enonce":"Touche le plus grand bénéfice du tableau.","aide":"Compare toutes les valeurs de B(x).","type":"zone","document":"pub","multiple":false},{"enonce":"Calcule B(4) = 10 ln 5 − 8, arrondi au centième.","aide":"ln 5 ≈ 1,6094.","type":"nombre"},{"enonce":"Que se passe-t-il pour le bénéfice quand x dépasse 4 ?","aide":"Calcule B′(9) = 10/10 − 2.","type":"choix","options":[{"id":"a","texte":"Il reste égal à 8,09 car B′(4) est égale à zéro"},{"id":"b","texte":"Il augmente encore, car B′(x) reste positive après x = 4"},{"id":"c","texte":"Il diminue, car B′(x) devient négative : trop de publicités coûte"},{"id":"d","texte":"Il devient négatif immédiatement, car ln(x + 1) change de signe"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3","explication":"B′(1) = 5 − 2 = **3** : le bénéfice augmente encore."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4","explication":"10 = 2(x + 1) donc x + 1 = 5 et **x = 4** : B′ s’annule en changeant de signe."},{"cle":{"type":"zone","ids":["r0c3"]},"explication":"Le maximum est **8,094** pour x = 4."},{"cle":{"type":"nombre","valeur":8.09,"tolerance":0.01},"affichage":"8,09","explication":"B(4) = 16,094 − 8 ≈ **8,09** milliers d’euros."},{"cle":{"type":"choix","ids":["c"]},"explication":"B′(9) = −1 < 0 : au-delà de 400 publicités, **le bénéfice diminue**."}]$ex$::jsonb),
  ('75d21456-1d9c-5eda-8771-6014ede38951'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le pic de la dose","competence":"modeliser","situation":"La quantité de principe actif dans le sang (en mg) est f(t) = t e^(−0,5 t), où t est en heures. Avec u = t (u′ = 1) et v = e^(−0,5 t) (v′ = −0,5 e^(−0,5 t)), on obtient f′ = u′v + uv′.","documents":[{"id":"calcul","type":"texte","genre":"consigne","titre":"Le calcul de f′","blocs":["f′(t) = 1 × e^(−0,5 t) + t × (−0,5 e^(−0,5 t)) = (1 − 0,5 t) e^(−0,5 t).","e^(−0,5 t) est toujours positif."]},{"id":"dose","type":"tableau","titre":"Quantité de principe actif","colonnes":["t (heures)","0","1","2","3","4","6"],"lignes":[["f(t) en mg",0,0.6065,0.7358,0.6694,0.5413,0.2987]],"enteteLignes":true,"source":"Valeurs imaginées pour l’exercice"}],"questions":[{"enonce":"Calcule f′(0) = (1 − 0) × e⁰.","aide":"e⁰ = 1.","type":"nombre"},{"enonce":"Pour quelle valeur de t le facteur 1 − 0,5 t est-il nul ?","aide":"Résous 1 − 0,5 t = 0.","type":"nombre"},{"enonce":"Touche la quantité maximale du tableau.","aide":"Compare les valeurs de la ligne f(t).","type":"zone","document":"dose","multiple":false},{"enonce":"Calcule f′(4) = (1 − 0,5 × 4) e^(−2), arrondi au centième.","aide":"e^(−2) ≈ 0,1353.","type":"nombre"},{"enonce":"Quelle est la dérivée de f(t) = t e^(−0,5 t) ?","aide":"Règle du produit : u′v + uv′.","type":"choix","options":[{"id":"a","texte":"(1 − 0,5 t) e^(−0,5 t), d’après la règle du produit"},{"id":"b","texte":"e^(−0,5 t), en ne dérivant que le facteur t seul"},{"id":"c","texte":"−0,5 t e^(−0,5 t), en ne dérivant que l’exponentielle"},{"id":"d","texte":"e^(−0,5 t) − 0,5 t, en dérivant chaque facteur seul"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":1,"tolerance":0},"affichage":"1","explication":"f′(0) = **1** : la quantité augmente au départ."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"0,5 t = 1 donc **t = 2 heures** : f′ s’annule en changeant de signe."},{"cle":{"type":"zone","ids":["r0c3"]},"explication":"Le maximum est **0,7358 mg** à t = 2 heures."},{"cle":{"type":"nombre","valeur":-0.14,"tolerance":0.01},"affichage":"−0,14","explication":"f′(4) = (−1) × 0,1353 ≈ **−0,14** : la quantité décroît après le pic."},{"cle":{"type":"choix","ids":["a"]},"explication":"La règle du produit donne **(1 − 0,5 t) e^(−0,5 t)** ; les autres réponses oublient un terme."}]$ex$::jsonb),
