:"zone","document":"produit","multiple":false},{"enonce":"Comment décrire le produit, avec f′ < 0 et f″ > 0 ?","aide":"Les pertes par heure diminuent.","type":"choix","options":[{"id":"a","texte":"Il augmente en ralentissant : f est croissante et concave"},{"id":"b","texte":"Il baisse en accélérant : f est décroissante et concave"},{"id":"c","texte":"Il augmente en accélérant : f est croissante et convexe"},{"id":"d","texte":"Il baisse en ralentissant : f est décroissante et convexe"}],"multiple":false}]}$ex$::jsonb,
