  ('37f61281-da6b-5f7b-afd4-783cd676cb0e'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le skateur sur la rampe","competence":"modeliser","situation":"Sur une rampe, la vitesse d’un skateur (en m/s) est v(t) = 2t, où t est le temps en secondes. Sa position x(t) sur la rampe est une primitive de v, avec x(0) = 0.","documents":[{"id":"rampe","type":"tableau","titre":"Vitesse et position du skateur","colonnes":["t (s)","0","1","2","3","4"],"lignes":[["v(t) en m/s",0,2,4,6,8],["x(t) en m",0,1,4,9,16]],"enteteLignes":true,"source":"Valeurs imaginées pour l’exercice"}],"questions":[{"enonce":"Touche la position du skateur à l’instant t = 3 s.","aide":"La position est sur la deuxième ligne.","type":"zone","document":"rampe","multiple":false},{"enonce":"Une primitive de v(t) = 2t est x(t) = t². Calcule la position à t = 5 s.","aide":"Remplace t par 5 dans t².","type":"nombre","unite":"m"},{"enonce":"Le skateur part en réalité de x(0) = 3 m. Quelle est alors sa position x(t) ?","aide":"Deux primitives de v diffèrent d’une constante.","type":"choix","options":[{"id":"a","texte":"x(t) = t² + 3, car la constante vaut la position de départ"},{"id":"b","texte":"x(t) = 3t², car la position de départ se multiplie à t²"},{"id":"c","texte":"x(t) = t² + 3t, car il faut multiplier la constante par t"},{"id":"d","texte":"x(t) = 2t² + 3, car on dérive la vitesse avant de conclure"}],"multiple":false},{"enonce":"Avec x(0) = 3 m, calcule la position à t = 4 s.","aide":"x(4) = 4² + 3.","type":"nombre","unite":"m"}]}$ex$::jsonb,
