  ('37f61281-da6b-5f7b-afd4-783cd676cb0e'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le médicament qui s’élimine","competence":"modeliser","situation":"Après une injection, la quantité y(t) de médicament dans le sang (en mg) vérifie y′ = −0,2 y, où t est en heures. À l’instant t = 0, on a y(0) = 50 mg.","documents":[{"id":"elim","type":"graphique","forme":"courbe","titre":"Quantité de médicament dans le sang","categories":["0","2","4","6","8","10"],"series":[{"nom":"y(t)","valeurs":[50,33.5,22.5,15.1,10.1,6.8],"teinte":"turquoise"}],"axeY":{"titre":"Quantité","unite":"mg","min":0,"max":50,"pas":10},"axeX":{"titre":"Temps (heures)"},"valeurs":false,"source":"Valeurs imaginées pour l’exercice"},{"id":"modele","type":"texte","genre":"consigne","titre":"Le modèle","blocs":["Les solutions de y′ = a y sont y(t) = C e^(a t).","Ici a = −0,2 et C = y(0) = 50."]}],"questions":[{"enonce":"Touche le premier point où la quantité passe sous 12 mg.","aide":"Lis les points de gauche à droite : cherche le premier sous 12 mg.","type":"zone","document":"elim","multiple":false},{"enonce":"Calcule y′(0) = −0,2 × y(0), la vitesse d’évolution au départ.","aide":"Multiplie −0,2 par 50.","type":"nombre","unite":"mg/h"},{"enonce":"Avec y(t) = 50 e^(−0,2 t), calcule y(5), arrondi au centième.","aide":"Pour t = 5, l’exposant vaut −1.","type":"nombre","unite":"mg"},{"enonce":"Quelle fonction est solution de y′ = −0,2 y avec y(0) = 50 ?","aide":"Les solutions de y′ = a y s’écrivent C e^(a t).","type":"choix","options":[{"id":"a","texte":"y(t) = 50 ln(0,2 t), car la quantité baisse lentement"},{"id":"b","texte":"y(t) = 50 e^(−0,2 t), car sa dérivée vaut −0,2 y(t)"},{"id":"c","texte":"y(t) = −0,2 e^(50 t), car 50 se place dans l’exposant"},{"id":"d","texte":"y(t) = 50 − 0,2 t, car elle baisse de 0,2 par heure"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k4"]},"explication":"À t = 8 h, la quantité vaut environ **10,1 mg** : c’est le premier point sous 12 mg."},{"cle":{"type":"nombre","valeur":-10,"tolerance":0},"affichage":"−10 mg/h","explication":"y′(0) = −0,2 × 50 = **−10 mg/h** : la quantité baisse de 10 mg par heure au départ."},{"cle":{"type":"nombre","valeur":18.39,"tolerance":0.01},"affichage":"18,39 mg","explication":"y(5) = 50 × e^(−1) ≈ 50 × 0,3679 ≈ **18,39 mg**."},{"cle":{"type":"choix","ids":["b"]},"explication":"La forme C e^(a t) avec a = −0,2 et C = 50 donne **y(t) = 50 e^(−0,2 t)**."}]$ex$::jsonb),
  ('37f61281-da6b-5f7b-afd4-783cd676cb0e'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le thé qui refroidit","competence":"modeliser","situation":"Un thé à 90 °C est posé dans une pièce à 20 °C. Sa température T(t) (en °C, t en minutes) vérifie T′ = −0,1 T + 2.","documents":[{"id":"the","type":"tableau","titre":"Température relevée","colonnes":["t (min)","0","5","10","15","20","30"],"lignes":[["T(t) en °C",90,62.5,45.8,35.6,29.5,23.5]],"enteteLignes":true,"source":"Valeurs imaginées pour l’exercice"},{"id":"meth","type":"texte","genre":"consigne","titre":"La méthode","blocs":["Solutions de y′ = a y + b : y(t) = C e^(a t) − b/a.","On détermine C avec la condition initiale T(0) = 90."]}],"questions":[{"enonce":"Ici a = −0,1 et b = 2. Calcule −b/a, la température d’équilibre.","aide":"Divise −2 par −0,1.","type":"nombre","unite":"°C"},{"enonce":"T(t) = C e^(−0,1 t) + 20. Avec T(0) = 90, que vaut C ?","aide":"À t = 0, e⁰ = 1 : C + 20 = 90.","type":"nombre"},{"enonce":"Calcule T(10) = 70 e^(−1) + 20, arrondi au dixième.","aide":"e^(−1) ≈ 0,3679.","type":"nombre","unite":"°C"},{"enonce":"Touche la température relevée la plus proche de la température d’équilibre.","aide":"Cherche la valeur la plus proche de 20 °C.","type":"zone","document":"the","multiple":false},{"enonce":"La pièce passe à 15 °C. Que devient la température d’équilibre du thé ?","aide":"Le refroidissement se fait vers la température ambiante.","type":"choix","options":[{"id":"a","texte":"Elle vaut 75 °C, car on retranche 15 à la température initiale"},{"id":"b","texte":"Elle vaut 90 °C, car le thé garde sa chaleur de départ"},{"id":"c","texte":"Elle reste 20 °C, car la température de départ ne change pas"},{"id":"d","texte":"Elle vaut 15 °C, car T′ = −0,1 T + 1,5 s’annule pour T = 15"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20 °C","explication":"−b/a = −2 / (−0,1) = **20 °C** : c’est la température de la pièce."},{"cle":{"type":"nombre","valeur":70,"tolerance":0},"affichage":"70","explication":"T(0) = C + 20 = 90 donne **C = 70**."},{"cle":{"type":"nombre","valeur":45.8,"tolerance":0.06},"affichage":"45,8 °C","explication":"T(10) = 70 × 0,3679 + 20 ≈ **45,8 °C**."},{"cle":{"type":"zone","ids":["r0c6"]},"explication":"À 30 min, le thé est à **23,5 °C** : proche de 20 °C, mais jamais égale."},{"cle":{"type":"choix","ids":["d"]},"explication":"L’équilibre est la température ambiante : **15 °C**, avec b = 0,1 × 15 = 1,5 et −b/a = 15."}]$ex$::jsonb),
