  ('6a81e6be-3fc7-5c44-b210-816c1492d0ee'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Les panneaux solaires du gymnase","competence":"modeliser","situation":"La puissance produite (en kW) par les panneaux du gymnase entre 9 h et 15 h est f(t) = 6t − t², où t est le nombre d’heures écoulées depuis 9 h. Une primitive de f est F(t) = 3t² − t³/3.","documents":[{"id":"puiss","type":"tableau","titre":"Puissance produite","colonnes":["t (h)","0","1,5","3","4,5","6"],"lignes":[["f(t) en kW",0,6.75,9,6.75,0]],"enteteLignes":true,"source":"Valeurs imaginées pour l’exercice"}],"questions":[{"enonce":"Touche la puissance maximale produite.","aide":"Cherche la plus grande valeur de la ligne.","type":"zone","document":"puiss","multiple":false},{"enonce":"Calcule l’énergie produite entre t = 0 et t = 3 : F(3) − F(0).","aide":"F(3) = 3 × 9 − 27/3.","type":"nombre","unite":"kWh"},{"enonce":"Calcule l’énergie produite entre 9 h et 15 h : F(6) − F(0).","aide":"F(6) = 3 × 36 − 216/3.","type":"nombre","unite":"kWh"},{"enonce":"Quelle est la puissance moyenne sur ces 6 heures ?","aide":"Divise l’énergie totale par la durée.","type":"nombre","unite":"kW"},{"enonce":"Pourquoi la puissance moyenne n’est-elle pas (f(0) + f(6)) / 2 ?","aide":"Que donnerait cette formule avec f(0) = f(6) = 0 ?","type":"choix","options":[{"id":"a","texte":"Parce que l’énergie se calcule toujours avec la médiane"},{"id":"b","texte":"Parce que la puissance varie et n’est pas affine sur l’intervalle"},{"id":"c","texte":"Parce que f(0) et f(6) sont des valeurs exprimées en heures"},{"id":"d","texte":"Parce que la moyenne d’une fonction n’existe jamais ici"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c3"]},"explication":"Le maximum est **9 kW**, à t = 3 h, soit à midi."},{"cle":{"type":"nombre","valeur":18,"tolerance":0},"affichage":"18 kWh","explication":"F(3) = 27 − 9 = 18 et F(0) = 0 : **18 kWh**."},{"cle":{"type":"nombre","valeur":36,"tolerance":0},"affichage":"36 kWh","explication":"F(6) = 108 − 72 = 36 et F(0) = 0 : **36 kWh**."},{"cle":{"type":"nombre","valeur":6,"tolerance":0},"affichage":"6 kW","explication":"36 / 6 = **6 kW**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Elle donnerait 0 kW alors que les panneaux produisent : elle n’est valable que pour une fonction **affine**."}]$ex$::jsonb),
  ('6a81e6be-3fc7-5c44-b210-816c1492d0ee'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le thermostat intelligent","competence":"analyser-document","situation":"Un lycée compare sa consommation de chauffage entre 8 h et 14 h (t en heures depuis 8 h). Sans programmation, elle vaut f(t) = 4 kW. Avec un thermostat programmé, elle vaut g(t) = (6t − t²)/3 kW, de primitive G(t) = (3t² − t³/3)/3.","documents":[{"id":"conso","type":"graphique","forme":"courbe","titre":"Consommation avec et sans thermostat","categories":["0","1.5","3","4.5","6"],"series":[{"nom":"Sans thermostat f(t)","valeurs":[4,4,4,4,4],"teinte":"corail"},{"nom":"Avec thermostat g(t)","valeurs":[0,2.25,3,2.25,0],"teinte":"turquoise"}],"axeY":{"titre":"Puissance","unite":"kW","min":0,"max":5,"pas":1},"axeX":{"titre":"Temps t (heures)"},"valeurs":false,"source":"Valeurs imaginées pour l’exercice"}],"questions":[{"enonce":"Touche l’instant où l’écart entre les deux consommations est le plus petit.","aide":"Compare l’écart vertical entre les deux courbes.","type":"zone","document":"conso","multiple":false},{"enonce":"Calcule l’énergie consommée sans thermostat sur [0 ; 6] : l’intégrale de la constante 4.","aide":"Constante × durée.","type":"nombre","unite":"kWh"},{"enonce":"Calcule l’énergie consommée avec thermostat : G(6) − G(0).","aide":"G(6) = (108 − 72)/3.","type":"nombre","unite":"kWh"},{"enonce":"Quelle énergie le thermostat économise-t-il sur la matinée ?","aide":"C’est l’intégrale de (f − g), l’écart cumulé.","type":"nombre","unite":"kWh"},{"enonce":"Quelle intégrale représente l’économie réalisée sur [0 ; 6] ?","aide":"L’aire entre deux courbes se calcule avec la courbe du haut moins celle du bas.","type":"choix","options":[{"id":"a","texte":"L’intégrale de f(t) + g(t), car on cumule les deux"},{"id":"b","texte":"L’intégrale de f(t) × g(t), car on combine les deux"},{"id":"c","texte":"L’intégrale de g(t) − f(t), car g est la plus récente"},{"id":"d","texte":"L’intégrale de f(t) − g(t), car f est au-dessus de g"}],"multiple":false}]}$ex$::jsonb,
