  ('030fabd4-24f7-50eb-b96b-069b43f57f47'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le test positif","competence":"analyser-document","situation":"Une maladie touche 2 % d’une population. Un test la détecte chez 95 % des malades (positif), mais donne un résultat positif à tort chez 10 % des personnes saines. Sur 10 000 personnes, on complète le tableau.","documents":[{"id":"test","type":"tableau","titre":"Résultats sur 10 000 personnes","colonnes":["","Malades","Bien portants","Total"],"lignes":[["Population",200,9800,10000],["Test positif","?","?","?"]],"enteteLignes":true,"source":"Effectifs calculés à partir des pourcentages de l’énoncé"}],"questions":[{"enonce":"Combien de malades ont un test positif ? (95 % de 200)","aide":"200 × 0,95.","type":"nombre"},{"enonce":"Combien de personnes saines ont un test positif à tort ? (10 % de 9 800)","aide":"9 800 × 0,10.","type":"nombre"},{"enonce":"Combien de personnes ont un test positif en tout ?","aide":"Additionne vrais et faux positifs.","type":"nombre"},{"enonce":"Un test est positif. Quelle est la probabilité que la personne soit malade ? Arrondi au centième.","aide":"Divise les malades positifs par tous les positifs.","type":"nombre"},{"enonce":"Que dire d’un résultat positif dans ce modèle ?","aide":"Compare 190 à 1 170.","type":"choix","options":[{"id":"a","texte":"Environ un positif sur deux est réellement malade"},{"id":"b","texte":"Presque tous les positifs sont réellement malades"},{"id":"c","texte":"Aucun des positifs n’est réellement malade"},{"id":"d","texte":"Environ un positif sur six est réellement malade"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":190,"tolerance":0},"affichage":"190","explication":"200 × 0,95 = **190 malades**."},{"cle":{"type":"nombre","valeur":980,"tolerance":0},"affichage":"980","explication":"9 800 × 0,1 = **980 faux positifs**."},{"cle":{"type":"nombre","valeur":1170,"tolerance":0},"affichage":"1170","explication":"190 + 980 = **1 170** tests positifs."},{"cle":{"type":"nombre","valeur":0.16,"tolerance":0.005},"affichage":"0,16","explication":"190 / 1 170 ≈ **0,16**. Seuls 16 % des positifs sont malades."},{"cle":{"type":"choix","ids":["d"]},"explication":"1 170 / 190 ≈ 6,2 : environ **1 positif sur 6** est malade, car les bien portants sont bien plus nombreux."}]$ex$::jsonb),
  ('ea6bb75c-d5e5-5584-b024-f2830abc825a'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le sondage de la mairie","competence":"lire-tableau","situation":"Avant un vote, un institut interroge 400 personnes choisies au hasard : 184 disent qu’elles voteront pour la liste Horizon. Pour une fréquence f observée sur n personnes, un intervalle de confiance à 95 % est [f − 1/√n ; f + 1/√n].","documents":[{"id":"sond","type":"tableau","titre":"Résultat du sondage","colonnes":["Personnes interrogées","Favorables à Horizon","Fréquence f"],"lignes":[["400","184","?"]],"enteteLignes":true,"source":"Valeurs imaginées pour l’exercice"}],"questions":[{"enonce":"Calcule la fréquence f de personnes favorables, en pourcentage.","aide":"Divise 184 par 400.","type":"nombre","unite":"%"},{"enonce":"Calcule la marge d’erreur 1/√400, en points de pourcentage.","aide":"√400 = 20.","type":"nombre","unite":"points"},{"enonce":"Quelle est la borne haute de l’intervalle de confiance, en pourcentage ?","aide":"Ajoute la marge à 46 %.","type":"nombre","unite":"%"},{"enonce":"Peut-on affirmer que la liste Horizon a moins de 50 % des voix ?","aide":"Regarde où se place 50 % par rapport aux deux bornes.","type":"choix","options":[{"id":"a","texte":"Non : 184 est plus grand que la moitié des 400 personnes"},{"id":"b","texte":"Non : 50 % est dans l’intervalle, qui va de 41 % à 51 %"},{"id":"c","texte":"Oui : la borne basse de 41 % est inférieure à 50 % au total"},{"id":"d","texte":"Oui : la fréquence observée de 46 % est inférieure à 50 %"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":46,"tolerance":0},"affichage":"46 %","explication":"184 / 400 = 0,46, soit **46 %**."},{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5 points","explication":"1/√400 = 1/20 = 0,05, soit **5 points**."},{"cle":{"type":"nombre","valeur":51,"tolerance":0},"affichage":"51 %","explication":"46 + 5 = **51 %**."},{"cle":{"type":"choix","ids":["b"]},"explication":"L’intervalle [41 % ; 51 %] contient 50 % : le sondage **ne permet pas de conclure**."}]$ex$::jsonb),
  ('ea6bb75c-d5e5-5584-b024-f2830abc825a'::uuid, 2, 2, 10, 35, 5,
