  ('ea6bb75c-d5e5-5584-b024-f2830abc825a'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Deux classes, une même moyenne","competence":"analyser-document","situation":"Deux classes de 5 élèves passent le même contrôle noté sur 20. Les deux professeurs annoncent la même moyenne. On veut savoir si les deux séries se ressemblent.","documents":[{"id":"notes","type":"tableau","titre":"Notes des deux classes","colonnes":["Élève","1","2","3","4","5"],"lignes":[["Classe A",9,10,10,10,11],["Classe B",4,8,10,12,16]],"enteteLignes":true,"source":"Valeurs imaginées pour l’exercice"},{"id":"rappel","type":"texte","genre":"consigne","titre":"Rappels","blocs":["Variance : moyenne des carrés des écarts à la moyenne.","Écart-type : racine carrée de la variance."]}],"questions":[{"enonce":"Calcule la moyenne de la classe B.","aide":"Additionne les 5 notes puis divise par 5.","type":"nombre"},{"enonce":"Calcule la variance de la classe B. Les écarts à 10 sont −6, −2, 0, 2, 6.","aide":"Élève les écarts au carré : 36, 4, 0, 4, 36.","type":"nombre"},{"enonce":"Calcule l’écart-type de la classe B.","aide":"Racine carrée de la variance.","type":"nombre","unite":"points"},{"enonce":"La variance de la classe A vaut 0,4. Calcule son écart-type, arrondi au centième.","aide":"√0,4 ≈ 0,632.","type":"nombre","unite":"point"},{"enonce":"Que peut-on conclure en comparant les deux classes ?","aide":"La moyenne ne dit rien de la dispersion.","type":"choix","options":[{"id":"a","texte":"Les deux classes ont des notes qui se ressemblent beaucoup"},{"id":"b","texte":"La classe A est moins bonne car son écart-type est plus petit"},{"id":"c","texte":"La classe B est meilleure car son écart-type est plus grand"},{"id":"d","texte":"Même moyenne, mais la classe B est bien plus dispersée"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":10,"tolerance":0},"affichage":"10","explication":"(4 + 8 + 10 + 12 + 16) / 5 = 50 / 5 = **10**."},{"cle":{"type":"nombre","valeur":16,"tolerance":0},"affichage":"16","explication":"(36 + 4 + 0 + 4 + 36) / 5 = 80 / 5 = **16**."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4 points","explication":"√16 = **4 points**."},{"cle":{"type":"nombre","valeur":0.63,"tolerance":0.005},"affichage":"0,63 point","explication":"√0,4 ≈ **0,63 point** : les notes sont très resserrées."},{"cle":{"type":"choix","ids":["d"]},"explication":"Écarts-types de 0,63 et 4 : **même centre, dispersion très différente**."}]$ex$::jsonb),
  ('21b56e3a-d75e-5510-8cfb-91ad28b464fe'::uuid, 1, 1, 5, 20, 4,
