  ('21b56e3a-d75e-5510-8cfb-91ad28b464fe'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le jeu de la fête foraine","competence":"raisonner","situation":"Un forain propose un jeu à 2 € la partie. Le gain brut X (en €, avant déduction de la mise) suit la loi du tableau. Le forain se demande à quel prix le jeu serait équitable, et comment varie le résultat.","documents":[{"id":"forain","type":"tableau","titre":"Loi du gain brut X","colonnes":["Gain X (€)","0","2","10"],"lignes":[["P(X = x)",0.6,0.3,0.1]],"enteteLignes":true,"source":"Valeurs imaginées pour l’exercice"},{"id":"rappel","type":"texte","genre":"consigne","titre":"Rappels","blocs":["V(X) = E(X²) − E(X)².","E(aX + b) = a E(X) + b et V(aX + b) = a² V(X)."]}],"questions":[{"enonce":"Calcule l’espérance du gain brut E(X).","aide":"0 × 0,6 + 2 × 0,3 + 10 × 0,1.","type":"nombre","unite":"€"},{"enonce":"À quelle mise le jeu serait-il équitable ?","aide":"Un jeu équitable a une espérance de gain net nulle.","type":"nombre","unite":"€"},{"enonce":"Calcule E(X²) = 0² × 0,6 + 2² × 0,3 + 10² × 0,1.","aide":"Élève chaque gain au carré avant de multiplier.","type":"nombre"},{"enonce":"En déduire V(X) = E(X²) − E(X)².","aide":"1,6² = 2,56.","type":"nombre"},{"enonce":"Le forain remplace le gain par Y = 3X + 1. Calcule V(Y).","aide":"Multiplie V(X) par 3².","type":"nombre"}]}$ex$::jsonb,
