   $ex${"titre":"Les paquets de farine","competence":"raisonner","situation":"Une machine remplit des paquets de farine. Leur masse X (en g) suit la loi normale de moyenne μ = 500 et d’écart-type σ = 10. Une production compte 1 000 paquets.","documents":[{"id":"repere","type":"tableau","titre":"Les trois repères de la loi normale","colonnes":["Intervalle","Part des valeurs"],"lignes":[["μ ± σ","environ 68 %"],["μ ± 2σ","environ 95 %"],["μ ± 3σ","environ 99,7 %"]],"enteteLignes":true}],"questions":[{"enonce":"Quelle est la borne basse de l’intervalle μ ± 2σ, en grammes ?","aide":"500 − 2 × 10.","type":"nombre","unite":"g"},{"enonce":"Combien de paquets pèsent entre 490 g et 510 g, soit μ ± σ ?","aide":"68 % de 1 000.","type":"nombre","unite":"paquets"},{"enonce":"Quel pourcentage de paquets pèse moins de 480 g ? Les deux extrémités se partagent les 5 % restants.","aide":"100 % − 95 % = 5 %, à partager.","type":"nombre","unite":"%"},{"enonce":"Combien de paquets environ pèsent moins de 470 g ou plus de 530 g, soit hors de μ ± 3σ ?","aide":"100 % − 99,7 % = 0,3 % de 1 000.","type":"nombre","unite":"paquets"},{"enonce":"Relie chaque intervalle de masse à la part des paquets qu’il contient.","aide":"Écris chaque intervalle sous la forme μ ± kσ.","type":"association","gauche":[{"id":"g0","texte":"De 490 g à 510 g"},{"id":"g1","texte":"De 480 g à 520 g"},{"id":"g2","texte":"De 470 g à 530 g"}],"droite":[{"id":"d0","texte":"environ 95 %"},{"id":"d1","texte":"environ 99,7 %"},{"id":"d2","texte":"environ 68 %"}]}]}$ex$::jsonb,
