   $ex${"titre":"La culture de bactéries","competence":"modeliser","situation":"Dans un laboratoire, on compte les bactéries d’une culture (en milliers) toutes les heures. Le nuage (x ; y) est courbe. On le redresse en posant z = ln(y), puis on ajuste z = a x + b par une droite.","documents":[{"id":"bact","type":"tableau","titre":"Comptages et changement de variable","colonnes":["Heure x","0","1","2","3","4"],"lignes":[["Bactéries y (milliers)",100,160,250,410,650],["z = ln(y)",4.61,5.08,5.52,"?",6.48]],"enteteLignes":true,"source":"Valeurs imaginées pour l’exercice ; z arrondi au centième"},{"id":"ajust","type":"texte","genre":"consigne","titre":"L’ajustement","blocs":["Par les moindres carrés sur (x ; z) : z = 0,47 x + 4,60 (coefficients arrondis au centième)."]}],"questions":[{"enonce":"Calcule z = ln(410) pour remplir la case manquante, arrondi au centième.","aide":"Utilise la touche ln de la calculatrice.","type":"nombre"},{"enonce":"Touche le nombre de bactéries comptées à l’heure 2.","aide":"Colonne « 2 » de la ligne des bactéries.","type":"zone","document":"bact","multiple":false},{"enonce":"Avec z = 0,47 x + 4,60, calcule z pour x = 5, l’heure suivante.","aide":"0,47 × 5 = 2,35.","type":"nombre"},{"enonce":"Revenu à y : y = e^z. Estime le nombre de bactéries (en milliers) à l’heure 5, arrondi à la dizaine.","aide":"Calcule e^6,95.","type":"nombre","unite":"milliers"},{"enonce":"Pourquoi poser z = ln(y) redresse-t-il le nuage ?","aide":"Si y = A e^(k x), que vaut ln(y) ?","type":"choix","options":[{"id":"a","texte":"Le logarithme rend toutes les valeurs de y égales entre elles"},{"id":"b","texte":"Un modèle exponentiel devient constant après passage au logarithme"},{"id":"c","texte":"Le logarithme transforme le nuage en un point unique de la droite"},{"id":"d","texte":"Un modèle exponentiel devient affine après passage au logarithme"}],"multiple":false}]}$ex$::jsonb,
