   $ex$[{"cle":{"type":"zone","ids":["k3"]},"explication":"Après le 4e rebond, la balle remonte à **0,82 m** : c’est la première hauteur sous 1 m (le 3e rebond donne 1,02 m)."},{"cle":{"type":"nombre","valeur":0.52,"tolerance":0.005},"affichage":"0,52 m","explication":"u(6) = 1,6 × 0,8^5 = 1,6 × 0,32768 ≈ **0,52 m**."},{"cle":{"type":"nombre","valeur":4.72,"tolerance":0.005},"affichage":"4,72 m","explication":"1,6 × (1 − 0,8^4) ÷ (1 − 0,8) = 1,6 × 0,5904 ÷ 0,2 ≈ **4,72 m**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Comme **0 < q < 1** et que les termes sont positifs, la suite est décroissante : chaque rebond est plus bas."}]$ex$::jsonb),
  ('207ce93d-e48a-5960-9908-dcf0d9b98020'::uuid, 3, 3, 15, 50, 5,
