  ('08c0214d-5006-583d-96c8-da970e78d49b'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Les abonnés de la chaîne","competence":"calculer","situation":"Une chaîne vidéo comptait 1 000 abonnés en 2021 et en compte 1 728 en 2024. Ses responsables veulent connaître la hausse annuelle moyenne sur ces trois années.","documents":[{"id":"abos","type":"tableau","titre":"Nombre d’abonnés","colonnes":["Année","2021","2024"],"lignes":[["Abonnés",1000,1728]],"enteteLignes":true,"source":"Valeurs imaginées pour l’exercice"}],"questions":[{"enonce":"Touche le nombre d’abonnés en 2024.","aide":"C’est la valeur finale.","type":"zone","document":"abos","multiple":false},{"enonce":"Calcule le coefficient multiplicateur global entre 2021 et 2024.","aide":"Valeur finale ÷ valeur initiale.","type":"nombre"},{"enonce":"Sachant que 1,2³ = 1,728, quel est le taux d’évolution annuel moyen, en pourcentage ?","aide":"Le coefficient moyen vérifie c³ = 1,728.","type":"nombre","unite":"%"},{"enonce":"Pourquoi ne divise-t-on pas les 72,8 % de hausse globale par 3 ?","aide":"Chaque année repart de la valeur de l’année précédente.","type":"choix","options":[{"id":"a","texte":"Chaque hausse annuelle s’applique à un nombre d’abonnés déjà augmenté"},{"id":"b","texte":"Les hausses annuelles s’additionnent, donc on divise bien par trois"},{"id":"c","texte":"Le nombre d’abonnés baisse chaque année, donc la division est fausse"},{"id":"d","texte":"72,8 % est trop grand, donc on l’arrondit à 70 % avant de diviser"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c2"]},"explication":"En 2024, la chaîne compte **1 728 abonnés**."},{"cle":{"type":"nombre","valeur":1.728,"tolerance":0},"affichage":"1,728","explication":"1 728 ÷ 1 000 = **1,728**."},{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20 %","explication":"Le coefficient moyen est **1,2** : une hausse de 20 % par an."},{"cle":{"type":"choix","ids":["a"]},"explication":"72,8 ÷ 3 ≈ 24,3 % ne redonne pas 1,728 : les hausses **se multiplient**, elles ne s’additionnent pas."}]$ex$::jsonb),
  ('08c0214d-5006-583d-96c8-da970e78d49b'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"La boulangerie et ses recettes","competence":"lire-graphique","situation":"Le chiffre d’affaires (CA) d’une boulangerie artisanale est relevé chaque année. Le gérant veut connaître sa croissance annuelle moyenne entre 2020 et 2024, soit sur 4 évolutions successives.","documents":[{"id":"ca","type":"graphique","forme":"barres","titre":"Chiffre d’affaires annuel","categories":["2020","2021","2022","2023","2024"],"series":[{"nom":"CA","valeurs":[150,156,165,172,184],"teinte":"ambre"}],"axeY":{"titre":"CA","unite":"en k€","min":0,"max":200,"pas":50},"axeX":{"titre":"Année"},"valeurs":false,"source":"Valeurs imaginées pour l’exercice"}],"questions":[{"enonce":"Touche l’année où la hausse par rapport à l’année précédente est la plus forte en valeur.","aide":"Calcule l’écart entre chaque barre et la précédente.","type":"zone","document":"ca","multiple":false},{"enonce":"Calcule le taux d’évolution global entre 2020 et 2024, en pourcentage arrondi au centième.","aide":"Coefficient : 184 ÷ 150, puis retire 1.","type":"nombre","unite":"%"},{"enonce":"Calcule le taux d’évolution annuel moyen, en pourcentage arrondi au centième.","aide":"Coefficient moyen : (184 ÷ 150)^(1/4).","type":"nombre","unite":"%"},{"enonce":"Au même rythme moyen pendant 2 années de plus, quel serait le CA en 2026 ? Arrondi à l’unité, en k€.","aide":"Multiplie 184 par le coefficient moyen, deux fois.","type":"nombre","unite":"k€"},{"enonce":"Le taux moyen est inférieur à 22,67 ÷ 4 ≈ 5,67 %. Pourquoi ?","aide":"Sur quelle valeur porte chaque hausse annuelle ?","type":"choix","options":[{"id":"a","texte":"Les hausses s’appliquent chaque année à un CA de plus en plus grand"},{"id":"b","texte":"La division par quatre ne convient pas car 2020 est une année de crise"},{"id":"c","texte":"Les hausses s’additionnent, donc il suffit de diviser le taux global"},{"id":"d","texte":"Les hausses successives se compensent, donc le taux moyen vaut zéro"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k4"]},"explication":"Les hausses sont 6 ; 9 ; 7 et **12 k€** : la plus forte est celle de 2024."},{"cle":{"type":"nombre","valeur":22.67,"tolerance":0.01},"affichage":"22,67 %","explication":"184 ÷ 150 ≈ 1,2267 : hausse de **22,67 %**."},{"cle":{"type":"nombre","valeur":5.24,"tolerance":0.01},"affichage":"5,24 %","explication":"(184 ÷ 150)^(1/4) ≈ 1,0524 : hausse moyenne de **5,24 % par an**."},{"cle":{"type":"nombre","valeur":204,"tolerance":0.6},"affichage":"204 k€","explication":"184 × 1,0524² ≈ **204 k€**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Chaque hausse porte sur un CA déjà augmenté : un taux plus petit suffit. Les évolutions **se multiplient**."}]$ex$::jsonb),
  ('08c0214d-5006-583d-96c8-da970e78d49b'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Du prix au livret","competence":"raisonner","situation":"Le prix d’un abonnement a connu trois évolutions annuelles successives, données ci-dessous. Par ailleurs, un livret rapporte 6 % par an : on cherche le taux mensuel qui donne le même résultat sur un an.","documents":[{"id":"prix","type":"tableau","titre":"Évolution du prix de l’abonnement","colonnes":["","Année 1","Année 2","Année 3"],"lignes":[["Évolution","+ 10 %","+ 20 %","− 5 %"],["Coefficient multiplicateur","1,1","1,2","0,95"]],"enteteLignes":true,"source":"Valeurs imaginées pour l’exercice"},{"id":"meth","type":"texte","genre":"consigne","titre":"La méthode","blocs":["Coefficient global : on multiplie les coefficients.","Taux moyen sur n périodes : C^(1/n) − 1.","Taux mensuel équivalent : (1 + t)^12 = coefficient annuel."]}],"questions":[{"enonce":"Touche l’évolution de l’année où le prix baisse.","aide":"Repère le signe de chaque évolution.","type":"zone","document":"prix","multiple":false},{"enonce":"Calcule le coefficient multiplicateur global des trois années.","aide":"Multiplie 1,1 × 1,2 × 0,95.","type":"nombre"},{"enonce":"Calcule le taux d’évolution annuel moyen sur les trois années, en pourcentage arrondi au centième.","aide":"Coefficient moyen : 1,254^(1/3).","type":"nombre","unite":"%"},{"enonce":"Pourquoi le taux moyen (7,84 %) diffère-t-il de la moyenne des pourcentages (8,33 %) ?","aide":"Un pourcentage s’applique à la valeur de l’année précédente.","type":"choix","options":[{"id":"a","texte":"La moyenne des pourcentages oublie la première année du tableau"},{"id":"b","texte":"Les évolutions se composent par multiplication et non par addition"},{"id":"c","texte":"Le taux moyen ignore la baisse de 5 % de la troisième année"},{"id":"d","texte":"Le taux moyen se calcule en divisant le taux global par trois"}],"multiple":false},{"enonce":"Quel est le taux mensuel équivalent à 6 % par an, en pourcentage arrondi au centième ?","aide":"Calcule 1,06^(1/12) puis retire 1.","type":"nombre","unite":"%"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c3"]},"explication":"À l’année 3, l’évolution est de **− 5 %** : c’est la seule baisse."},{"cle":{"type":"nombre","valeur":1.254,"tolerance":0.0005},"affichage":"1,254","explication":"1,1 × 1,2 × 0,95 = **1,254**."},{"cle":{"type":"nombre","valeur":7.84,"tolerance":0.01},"affichage":"7,84 %","explication":"1,254^(1/3) ≈ 1,0784 : **+ 7,84 % par an** en moyenne."},{"cle":{"type":"choix","ids":["b"]},"explication":"On ne peut pas additionner des pourcentages qui portent sur des bases différentes : les coefficients **se multiplient**."},{"cle":{"type":"nombre","valeur":0.49,"tolerance":0.01},"affichage":"0,49 %","explication":"1,06^(1/12) ≈ 1,00487 : **0,49 % par mois**, un peu moins que 6 ÷ 12 = 0,5 %."}]$ex$::jsonb),
  ('e2e23011-e7b4-5a93-986e-cde80b643ed4'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"L’échelle des pH","competence":"lire-tableau","situation":"En chimie, le pH d’une solution se calcule avec le logarithme décimal : pH = −log [H₃O⁺], où [H₃O⁺] est la concentration en ions oxonium, en mol/L. Plus le pH est petit, plus la solution est acide.","documents":[{"id":"ph","type":"tableau","titre":"Trois solutions du quotidien","colonnes":["Solution","Citron","Café","Eau pure"],"lignes":[["[H₃O⁺] (mol/L)","10^(−2)","10^(−5)","10^(−7)"],["pH",2,5,"?"]],"enteteLignes":true,"source":"Valeurs arrondies, à titre d’exemple"}],"questions":[{"enonce":"Complète la case « ? » : quel est le pH de l’eau pure ?","aide":"log(10^(−7)) = −7, donc pH = −(−7).","type":"nombre"},{"enonce":"Touche le pH de la solution la plus acide.","aide":"Plus le pH est petit, plus la solution est acide.","type":"zone","document":"ph","multiple":false},{"enonce":"Quelle est la concentration [H₃O⁺] d’une solution de pH 4 ? Écris-la en décimal (mol/L).","aide":"pH = 4 signifie log[H₃O⁺] = −4, soit [H₃O⁺] = 10^(−4).","type":"nombre","unite":"mol/L"},{"enonce":"La concentration [H₃O⁺] est multipliée par 100. Que devient le pH ?","aide":"Utilise log(100 × a) = log(100) + log(a).","type":"choix","options":[{"id":"a","texte":"Il diminue de 2 points, car le logarithme de 100 vaut 2"},{"id":"b","texte":"Il est divisé par 100, car le pH est proportionnel à [H₃O⁺]"},{"id":"c","texte":"Il augmente de 2 points, car le logarithme de 100 vaut 2"},{"id":"d","texte":"Il est multiplié par 100, car le pH est proportionnel à [H₃O⁺]"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":7,"tolerance":0},"affichage":"7","explication":"pH = −log(10^(−7)) = −(−7) = **7**."},{"cle":{"type":"zone","ids":["r1c1"]},"explication":"Le citron a le pH le plus petit (**2**) : c’est la solution la plus acide."},{"cle":{"type":"nombre","valeur":0.0001,"tolerance":0},"affichage":"0,0001 mol/L","explication":"[H₃O⁺] = 10^(−4) = **0,0001 mol/L**."},{"cle":{"type":"choix","ids":["a"]},"explication":"log(100 × a) = 2 + log(a) : le logarithme gagne 2, donc le pH = −log **perd 2 points**."}]$ex$::jsonb),
  ('e2e23011-e7b4-5a93-986e-cde80b643ed4'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Combien de chiffres ?","competence":"calculer","situation":"Une calculatrice affiche « Erreur » pour 3^50, trop grand pour son écran. Un élève veut savoir combien de chiffres compte ce nombre, en s’aidant du tableau de valeurs du logarithme décimal.","documents":[{"id":"logs","type":"tableau","titre":"Quelques logarithmes décimaux (arrondis au millième)","colonnes":["a","2","3","5","7"],"lignes":[["log(a)",0.301,0.477,"?",0.845]],"enteteLignes":true,"source":"Valeurs arrondies au millième"},{"id":"regles","type":"texte","genre":"consigne","titre":"Règles","blocs":["log(a × b) = log(a) + log(b).","log(a^n) = n × log(a).","Un entier N compte k chiffres si k − 1 ≤ log(N) < k."]}],"questions":[{"enonce":"Complète la case « ? » : calcule log(5) sachant que 5 = 10 ÷ 2.","aide":"log(10 ÷ 2) = log(10) − log(2) = 1 − log(2).","type":"nombre"},{"enonce":"Calcule log(6) à partir du tableau, sachant que 6 = 2 × 3.","aide":"Additionne log(2) et log(3).","type":"nombre"},{"enonce":"Touche le nombre a dont le logarithme est le plus proche de 0,5.","aide":"Compare 0,301 ; 0,477 ; 0,699 et 0,845 à 0,5.","type":"zone","document":"logs","multiple":false},{"enonce":"Calcule log(3^50) avec la règle log(a^n) = n × log(a).","aide":"Multiplie log(3) par 50.","type":"nombre"},{"enonce":"Combien de chiffres compte 3^50 ?","aide":"Un nombre compte k chiffres si k − 1 ≤ log(N) < k.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":0.699,"tolerance":0.001},"affichage":"0,699","explication":"log(5) = 1 − 0,301 = **0,699**."},{"cle":{"type":"nombre","valeur":0.778,"tolerance":0.001},"affichage":"0,778","explication":"log(6) = 0,301 + 0,477 = **0,778**."},{"cle":{"type":"zone","ids":["r0c2"]},"explication":"log(3) = 0,477 est le plus proche de 0,5 : c’est le nombre **3**."},{"cle":{"type":"nombre","valeur":23.85,"tolerance":0.02},"affichage":"23,85","explication":"log(3^50) = 50 × 0,477 = **23,85**."},{"cle":{"type":"nombre","valeur":24,"tolerance":0},"affichage":"24","explication":"23 ≤ 23,85 < 24 donc k = **24 chiffres**."}]$ex$::jsonb),
  ('e2e23011-e7b4-5a93-986e-cde80b643ed4'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le laboratoire en échelle log","competence":"modeliser","situation":"Dans une culture, le nombre de bactéries double chaque heure : N(t) = 100 × 2^t, avec t en heures. Un biologiste reporte aussi log N(t), ce qui aligne les points et simplifie les calculs.","documents":[{"id":"bacts","type":"tableau","titre":"Population et son logarithme","colonnes":["t (h)","0","1","2","3","4","5"],"lignes":[["N(t)",100,200,400,800,1600,3200],["log N(t)",2,2.301,2.602,"?",3.204,3.505]],"enteteLignes":true,"source":"Logarithmes arrondis au millième"},{"id":"regles","type":"texte","genre":"consigne","titre":"Règles","blocs":["log(a × b) = log(a) + log(b) ; log(a^n) = n × log(a).","log(2) ≈ 0,301."]}],"questions":[{"enonce":"Complète la case « ? » : calcule log N(3) = log(800).","aide":"log(800) = log(8) + log(100) = 3 × 0,301 + 2.","type":"nombre"},{"enonce":"De combien log N(t) augmente-t-il à chaque heure ?","aide":"Comparer deux colonnes voisines de la ligne log N(t).","type":"nombre"},{"enonce":"Touche la première population qui dépasse 1 000 bactéries.","aide":"Parcours la ligne N(t) de gauche à droite.","type":"zone","document":"bacts","multiple":false},{"enonce":"On a log N(t) = 2 + 0,301 t. Pour N = 10 000, log N vaut 4 : calcule t, arrondi au dixième.","aide":"Résous 2 + 0,301 t = 4.","type":"nombre","unite":"h"},{"enonce":"Pourquoi les points (t ; log N) sont-ils alignés ?","aide":"Utilise log(2 × N) = log(2) + log(N).","type":"choix","options":[{"id":"a","texte":"Chaque heure, N augmente de 100, donc log N augmente de 100"},{"id":"b","texte":"Chaque heure, N est multiplié par 2, donc log N augmente de log 2"},{"id":"c","texte":"Chaque heure, N est multiplié par 2, donc log N est multiplié par 2"},{"id":"d","texte":"Chaque heure, N augmente de 2, donc log N augmente de log 2"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":2.903,"tolerance":0.001},"affichage":"2,903","explication":"log(800) = 2 + 3 × 0,301 = **2,903**."},{"cle":{"type":"nombre","valeur":0.301,"tolerance":0.001},"affichage":"0,301","explication":"Chaque heure, N est multiplié par 2, donc log N augmente de **log(2) ≈ 0,301**."},{"cle":{"type":"zone","ids":["r0c5"]},"explication":"À t = 4 h, N = **1 600** : c’est la première valeur au-dessus de 1 000."},{"cle":{"type":"nombre","valeur":6.6,"tolerance":0.05},"affichage":"6,6 h","explication":"0,301 t = 2 donc t = 2 ÷ 0,301 ≈ **6,6 heures**."},{"cle":{"type":"choix","ids":["b"]},"explication":"log(2 × N) = log 2 + log N : **on ajoute toujours la même quantité**, les points sont alignés."}]$ex$::jsonb),
  ('c76410fa-a5a4-5e1d-9bbd-d11ce2ee7274'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le livret qui double","competence":"resoudre","situation":"Un capital de 1 000 € est placé à 4 % par an. Au bout de n années, il vaut C(n) = 1 000 × 1,04^n. On cherche quand il aura doublé.","documents":[{"id":"livret","type":"tableau","titre":"Capital au fil des années","colonnes":["Année","0","5","10","15","20"],"lignes":[["Capital (€)",1000,1216.65,1480.24,1800.94,2191.12]],"enteteLignes":true,"source":"Valeurs arrondies au centime, imaginées pour l’exercice"},{"id":"logs","type":"texte","genre":"consigne","titre":"Valeurs utiles","blocs":["log(2) ≈ 0,3010 et log(1,04) ≈ 0,0170.","a^n ≥ b équivaut à n × log(a) ≥ log(b)."]}],"questions":[{"enonce":"Touche le premier capital qui dépasse 2 000 €.","aide":"Parcours la ligne de gauche à droite.","type":"zone","document":"livret","multiple":false},{"enonce":"Résous 1,04^n ≥ 2 : calcule log(2) ÷ log(1,04), arrondi au dixième.","aide":"Divise 0,3010 par 0,0170.","type":"nombre"},{"enonce":"Au bout de combien d’années entières le capital a-t-il doublé ?","aide":"n doit être un entier supérieur ou égal à 17,7.","type":"nombre"},{"enonce":"Pourquoi garde-t-on le même sens d’inégalité en divisant par log(1,04) ?","aide":"Quel est le signe de log(b) quand b > 1 ?","type":"choix","options":[{"id":"a","texte":"Car log(1,04) est positif, puisque 1,04 est supérieur à 1"},{"id":"b","texte":"Car log(1,04) est nul, puisque 1,04 est proche de 1"},{"id":"c","texte":"Car log(1,04) est négatif, puisque 1,04 est supérieur à 1"},{"id":"d","texte":"Car log(1,04) est positif, puisque 1,04 est inférieur à 1"}],"multiple":false}]}$ex$::jsonb,
