  ('c76410fa-a5a4-5e1d-9bbd-d11ce2ee7274'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Le stock qui fond","competence":"resoudre","situation":"Une pharmacie a 5 000 boîtes en stock et en vend 10 % du stock restant chaque semaine, sans réapprovisionner. Le stock après n semaines est S(n) = 5 000 × 0,9^n. La pharmacie commande de nouveau quand il reste moins de 1 000 boîtes.","documents":[{"id":"stock","type":"graphique","forme":"courbe","titre":"Stock restant","categories":["0","4","8","12","16","20"],"series":[{"nom":"S(n)","valeurs":[5000,3281,2152,1412,927,608],"teinte":"turquoise"}],"axeY":{"titre":"Stock","unite":"en boîtes","min":0,"max":5000,"pas":1000},"axeX":{"titre":"Semaines n"},"valeurs":false,"source":"Valeurs arrondies à l’unité, imaginées pour l’exercice"},{"id":"logs","type":"texte","genre":"consigne","titre":"Valeurs utiles","blocs":["log(0,2) ≈ −0,699 et log(0,9) ≈ −0,0458.","S(n) < 1 000 équivaut à 0,9^n < 0,2."]}],"questions":[{"enonce":"Touche le premier point où le stock passe sous 1 000 boîtes.","aide":"Parcours la courbe de gauche à droite.","type":"zone","document":"stock","multiple":false},{"enonce":"Résous 0,9^n < 0,2 : calcule log(0,2) ÷ log(0,9), arrondi au dixième.","aide":"Divise −0,699 par −0,0458.","type":"nombre"},{"enonce":"À partir de quelle semaine entière le stock est-il inférieur à 1 000 boîtes ?","aide":"n doit être un entier strictement supérieur à 15,3.","type":"nombre"},{"enonce":"Vérifie : calcule S(15), le stock après 15 semaines, arrondi à l’unité.","aide":"0,9^15 ≈ 0,2059.","type":"nombre","unite":"boîtes"},{"enonce":"Que devient le sens de l’inégalité quand on divise par log(0,9) ?","aide":"Quel est le signe de log(0,9), sachant que 0,9 < 1 ?","type":"choix","options":[{"id":"a","texte":"Il reste le même, car 0,9 est un nombre positif, donc log(0,9) aussi"},{"id":"b","texte":"Il change de sens, car on divise les deux membres par un nombre négatif"},{"id":"c","texte":"Il change de sens, car on divise les deux membres par un nombre positif"},{"id":"d","texte":"Il reste le même, car on divise les deux membres par un nombre négatif"}],"multiple":false}]}$ex$::jsonb,
