  ('1b8f67c6-66fe-5484-9eb3-ef51b7d5a537'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La tangente du coût moyen","competence":"modeliser","situation":"Une fabrique de bougies modélise son coût moyen par CM(q) = 2 + 8 ÷ q, où q est le nombre de bougies produites en centaines et CM(q) un coût en euros. On étudie sa variation et sa tangente au point d’abscisse 4.","documents":[{"id":"coutm","type":"tableau","titre":"Coût moyen selon la production","colonnes":["q (centaines)","1","2","4","8"],"lignes":[["CM(q) (€)",10,6,4,3]],"enteteLignes":true,"source":"Valeurs imaginées pour l’exercice"},{"id":"deriv","type":"texte","genre":"consigne","titre":"Rappels","blocs":["(1 ÷ x)′ = −1 ÷ x², donc CM′(q) = −8 ÷ q².","Tangente en a : y = CM′(a) × (x − a) + CM(a)."]}],"questions":[{"enonce":"Touche le coût moyen qui vaut 4 €.","aide":"Lis la ligne CM(q).","type":"zone","document":"coutm","multiple":false},{"enonce":"Calcule CM′(2).","aide":"CM′(2) = −8 ÷ 2².","type":"nombre"},{"enonce":"Calcule CM′(4), le coefficient directeur de la tangente en 4.","aide":"CM′(4) = −8 ÷ 4².","type":"nombre"},{"enonce":"La tangente en 4 s’écrit y = −0,5 × (x − 4) + 4. Quelle est son ordonnée à l’origine ?","aide":"Développe, puis regarde la valeur de y quand x = 0.","type":"nombre"},{"enonce":"Que dit le signe de CM′(q) sur la variation de CM ?","aide":"Un nombre dérivé négatif correspond à une fonction qui descend.","type":"choix","options":[{"id":"a","texte":"CM′(q) = −8 ÷ q² est négatif pour tout q > 0, donc CM est croissante"},{"id":"b","texte":"CM′(q) = 8 ÷ q² est positif pour tout q > 0, donc CM est décroissante"},{"id":"c","texte":"CM′(q) = −8 ÷ q² est négatif pour tout q > 0, donc CM est décroissante"},{"id":"d","texte":"CM′(q) = 8 ÷ q² est positif pour tout q > 0, donc CM est croissante"}],"multiple":false}]}$ex$::jsonb,
